===== Tenure.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * The single definition of an owner's "tenure": the number of whole days that have elapsed
 * since the owner's registration date. A newly registered owner — one registered as of the
 * reference date — has zero tenure. Provides the measure {@link AssignMembershipLevel} uses to
 * gate the top membership level, which is reserved for long-standing owners.
 */
final class Tenure {

    private Tenure() {
    }

    /** Whole days between {@code registrationDate} and {@code asOf}; zero when the date is
     *  unset or still in the future. */
    static long days(LocalDate registrationDate, LocalDate asOf) {
        if (registrationDate == null) {
            return 0;
        }
        return Math.max(ChronoUnit.DAYS.between(registrationDate, asOf), 0);
    }
}
===== BusinessDay.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Set;

/**
 * The single definition of a "business day" for owner registration: a weekday (Monday–Friday)
 * that is not a listed public holiday. A date that falls on a weekend or a public holiday is
 * rolled forward to the next such business day; a plain weekday is returned unchanged. Used so
 * every effective registration date — whether supplied in the request or defaulted to the server
 * date — lands on a business day, and so the daily create-limit buckets owners by that same
 * adjusted day.
 */
final class BusinessDay {

    /** Fixed public-holiday calendar; a date landing on one of these rolls forward. */
    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
            LocalDate.of(2026, 1, 1),
            LocalDate.of(2026, 1, 26),
            LocalDate.of(2026, 4, 25),
            LocalDate.of(2026, 12, 25),
            LocalDate.of(2026, 12, 28));

    private BusinessDay() {
    }

    /** {@code date} rolled forward to the next business day when it falls on a weekend or public holiday, else unchanged. */
    static LocalDate adjust(LocalDate date) {
        while (!isBusinessDay(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    private static boolean isBusinessDay(LocalDate date) {
        DayOfWeek dayOfWeek = date.getDayOfWeek();
        return dayOfWeek != DayOfWeek.SATURDAY && dayOfWeek != DayOfWeek.SUNDAY
                && !PUBLIC_HOLIDAYS.contains(date);
    }
}
===== ResolveOwnerRegistrationDate.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Step of {@code POST /api/owners}: resolves the new owner's effective registration date and
 * ensures it falls on a business day. The effective date is the one supplied in the request,
 * or the server's current date when the request supplied none; either way, a weekend date is
 * rolled forward to the following Monday (see {@link BusinessDay}). Runs on the built owner so
 * both the persisted row and the response — and every value derived from the date, such as the
 * membership number's year segment — carry the adjusted value.
 */
public class ResolveOwnerRegistrationDate {

    public void service(@Val Owner owner) {
        LocalDate effective = owner.getRegistrationDate();
        if (effective == null) {
            effective = LocalDate.now();
        }
        owner.setRegistrationDate(BusinessDay.adjust(effective));
    }
}
===== Namesake.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of an owner "namesake": two owners are namesakes when they share
 * the same first name and last name, compared case-insensitively (leading and trailing
 * whitespace ignored). Provides the membership test used to count how many existing owners
 * a new owner shares a name with.
 *
 * @see CountNamesakes counts the matching owners at registration.
 */
final class Namesake {

    private Namesake() {
    }

    /** Whether {@code owner} is a namesake of the owner named {@code firstName} {@code lastName}. */
    static boolean matches(Owner owner, String firstName, String lastName) {
        return normalize(owner.getFirstName()).equals(normalize(firstName))
                && normalize(owner.getLastName()).equals(normalize(lastName));
    }

    /** A name trimmed and lower-cased, so comparison is case-insensitive. */
    private static String normalize(String value) {
        return value == null ? "" : value.strip().toLowerCase(Locale.ROOT);
    }
}
===== AssignMembershipLevel.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners}: assigns the new owner's {@code membershipPoints} and the
 * {@code membershipLevel} derived from them. The scoring rules and the points-to-level
 * mapping live in {@link MembershipPoints}; this step gathers the factors and stores both
 * values. It runs after {@link CountNamesakes} so the namesake count is known,
 * {@link AssignHousehold} so the household is stamped, and
 * {@link ResolveOwnerRegistrationDate} so the registration date is resolved, and before
 * {@link SaveOwner} persists the owner and {@link AuditOwnerCreated} records the level. The
 * values are stored with the row and returned unchanged on later reads.
 */
public class AssignMembershipLevel {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        // The new owner is not yet persisted, so it is counted here rather than by the repository.
        long householdSize = Household.size(owner.getHouseholdId(), ownerRepository.findAll()) + 1;
        long tenureDays = Tenure.days(owner.getRegistrationDate(), LocalDate.now());
        int points = MembershipPoints.score(owner.getEmail(), owner.getNamesakeCount(), householdSize, tenureDays);
        owner.setMembershipPoints(points);
        owner.setMembershipLevel(MembershipPoints.level(points));
    }
}
===== MembershipPoints.java =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * The membership points system. An owner's score starts at 0 and gains points for the
 * factors below; the score then maps to a membership level. The single place these rules
 * live, keeping {@link AssignMembershipLevel} to orchestration.
 *
 * <ul>
 *   <li>+2 when an email is on file,</li>
 *   <li>+1 when the owner has no namesakes ({@code namesakeCount} is 0),</li>
 *   <li>+2 for a household of {@value #LARGE_HOUSEHOLD_SIZE} or more,</li>
 *   <li>+3 for tenure over {@value #LONG_TENURE_DAYS} days.</li>
 * </ul>
 *
 * The resulting points map to a level: 1 for 0-1, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
 */
final class MembershipPoints {

    private static final int EMAIL_POINTS = 2;
    private static final int NO_NAMESAKES_POINTS = 1;
    private static final int LARGE_HOUSEHOLD_POINTS = 2;
    private static final int LONG_TENURE_POINTS = 3;

    /** Smallest household size that earns the household points. */
    private static final int LARGE_HOUSEHOLD_SIZE = 3;
    /** Tenure, in days, that must be exceeded to earn the tenure points. */
    private static final long LONG_TENURE_DAYS = 365;

    private MembershipPoints() {
    }

    /** The owner's membership score from its factors. */
    static int score(String email, Integer namesakeCount, long householdSize, long tenureDays) {
        int points = 0;
        if (email != null && !email.isBlank()) {
            points += EMAIL_POINTS;
        }
        if (namesakeCount != null && namesakeCount == 0) {
            points += NO_NAMESAKES_POINTS;
        }
        if (householdSize >= LARGE_HOUSEHOLD_SIZE) {
            points += LARGE_HOUSEHOLD_POINTS;
        }
        if (tenureDays > LONG_TENURE_DAYS) {
            points += LONG_TENURE_POINTS;
        }
        return points;
    }

    /** The membership level a score maps to: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6+). */
    static int level(int points) {
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }
}
===== AgeBand.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.time.Period;

/**
 * The single definition of an owner's age band: the owner's age in whole years at its
 * registration date, bucketed as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or
 * {@code "SENIOR"} (65 and over).
 *
 * <p>Lookup only; a pure function of the birth date and registration date, so the band is
 * computed on read rather than stored. Absent (null) until both dates are known.
 */
public final class AgeBand {

    /** Age (inclusive) at which an owner becomes an adult. */
    private static final int ADULT_AGE = 18;

    /** Age (inclusive) at which an owner becomes a senior. */
    private static final int SENIOR_AGE = 65;

    private AgeBand() {
    }

    /** The age band for someone born on {@code birthDate} as measured on {@code registrationDate},
     *  or {@code null} when either date is absent. */
    public static String of(LocalDate birthDate, LocalDate registrationDate) {
        if (birthDate == null || registrationDate == null) {
            return null;
        }
        int years = Period.between(birthDate, registrationDate).getYears();
        if (years < ADULT_AGE) {
            return "MINOR";
        }
        return years < SENIOR_AGE ? "ADULT" : "SENIOR";
    }
}

