10	/**
11	 * Step of {@code POST /api/owners}: assigns the new owner's {@code customerCode}. The code is
12	 * {@code <REGION>-<HASH8>} — the region derived from the owner's postcode (see
13	 * {@link Locality}) and a stable hash of the owner's normalized telephone and last name; it
14	 * carries no sequence number. It runs after the telephone has been normalized (so the hash
15	 * covers the E.164 value) and is persisted with the row and returned on later reads.
16	 *
17	 * <p>Should the formatted code collide with an existing owner's {@code customerCode}, it is
18	 * de-duplicated by appending {@code -<n>} (see {@link CustomerCode#deduplicate}).
19	 *
20	 * @see CustomerCode for the {@code <REGION>-<HASH8>} format.
21	 */
22	public class AssignOwnerCustomerCode {
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
25	        String region = Locality.region(owner.getCity(), owner.getPostcode());
26	        String code = CustomerCode.format(region, owner.getTelephone(), owner.getLastName());
27	        Set<String> inUse = new HashSet<>();
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (existing.getCustomerCode() != null) {
30	                inUse.add(existing.getCustomerCode());
31	            }
32	        }
33	        owner.setCustomerCode(CustomerCode.deduplicate(code, inUse::contains));
34	    }
35	}
