1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * The single definition of a "business day" for owner registration: a weekday (Monday–Friday)
9	 * that is not a listed public holiday. A date that falls on a weekend or a public holiday is
10	 * rolled forward to the next such business day; a plain weekday is returned unchanged. Used so
11	 * every effective registration date — whether supplied in the request or defaulted to the server
12	 * date — lands on a business day, and so the daily create-limit buckets owners by that same
13	 * adjusted day.
14	 */
15	final class BusinessDay {
16	
17	    /** Fixed public-holiday calendar; a date landing on one of these rolls forward. */
18	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
19	            LocalDate.of(2026, 1, 1),
20	            LocalDate.of(2026, 1, 26),
21	            LocalDate.of(2026, 4, 25),
22	            LocalDate.of(2026, 12, 25),
23	            LocalDate.of(2026, 12, 28));
24	
25	    private BusinessDay() {
26	    }
27	
28	    /** {@code date} rolled forward to the next business day when it falls on a weekend or public holiday, else unchanged. */
29	    static LocalDate adjust(LocalDate date) {
30	        while (!isBusinessDay(date)) {
31	            date = date.plusDays(1);
32	        }
33	        return date;
34	    }
35	
36	    private static boolean isBusinessDay(LocalDate date) {
37	        DayOfWeek dayOfWeek = date.getDayOfWeek();
38	        return dayOfWeek != DayOfWeek.SATURDAY && dayOfWeek != DayOfWeek.SUNDAY
39	                && !PUBLIC_HOLIDAYS.contains(date);
40	    }
41	}
