19	public class AssignMembershipLevel {
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
22	        // The new owner is not yet persisted, so it is counted here rather than by the repository.
23	        long householdSize = Household.size(owner.getHouseholdId(), ownerRepository.findAll()) + 1;
24	        long tenureDays = Tenure.days(owner.getRegistrationDate(), LocalDate.now());
25	        int points = MembershipPoints.score(owner.getEmail(), owner.getNamesakeCount(), householdSize, tenureDays);
26	        owner.setMembershipPoints(points);
27	        owner.setMembershipLevel(MembershipPoints.level(points));
28	    }
