1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * The membership points system. An owner's score starts at 0 and gains points for the
5	 * factors below; the score then maps to a membership level. The single place these rules
6	 * live, keeping {@link AssignMembershipLevel} to orchestration.
7	 *
8	 * <ul>
9	 *   <li>+2 when an email is on file,</li>
10	 *   <li>+1 when the owner has no namesakes ({@code namesakeCount} is 0),</li>
11	 *   <li>+2 for a household of {@value #LARGE_HOUSEHOLD_SIZE} or more,</li>
12	 *   <li>+3 for tenure over {@value #LONG_TENURE_DAYS} days.</li>
13	 * </ul>
14	 *
15	 * The resulting points map to a level: 1 for 0-1, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
16	 */
17	final class MembershipPoints {
18	
19	    private static final int EMAIL_POINTS = 2;
20	    private static final int NO_NAMESAKES_POINTS = 1;
21	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
22	    private static final int LONG_TENURE_POINTS = 3;
23	
24	    /** Smallest household size that earns the household points. */
25	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
26	    /** Tenure, in days, that must be exceeded to earn the tenure points. */
27	    private static final long LONG_TENURE_DAYS = 365;
28	
29	    private MembershipPoints() {
30	    }
31	
32	    /** The owner's membership score from its factors. */
33	    static int score(String email, Integer namesakeCount, long householdSize, long tenureDays) {
34	        int points = 0;
35	        if (email != null && !email.isBlank()) {
36	            points += EMAIL_POINTS;
37	        }
38	        if (namesakeCount != null && namesakeCount == 0) {
39	            points += NO_NAMESAKES_POINTS;
40	        }
41	        if (householdSize >= LARGE_HOUSEHOLD_SIZE) {
42	            points += LARGE_HOUSEHOLD_POINTS;
43	        }
44	        if (tenureDays > LONG_TENURE_DAYS) {
45	            points += LONG_TENURE_POINTS;
46	        }
47	        return points;
48	    }
49	
50	    /** The membership level a score maps to: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6+). */
51	    static int level(int points) {
52	        if (points <= 1) {
53	            return 1;
54	        }
55	        if (points <= 3) {
56	            return 2;
57	        }
58	        if (points <= 5) {
59	            return 3;
60	        }
61	        return 4;
62	    }
63	}
