package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.time.Month;

/**
 * The single definition of the fiscal year, which starts on 1 July. A date on or after
 * 1 July belongs to the fiscal year beginning in that calendar year; a date before 1 July
 * belongs to the fiscal year that began the previous calendar year. A fiscal year is
 * identified by the calendar year in which it starts and labelled {@code "FY<YY>"} from that
 * year's last two digits (e.g. 1 July 2026 – 30 June 2027 is {@code "FY26"}).
 *
 * <p>Provides the fiscal basis for every date-derived value: the membership number's year
 * segment and the {@code fiscalYear} field (both via {@code OwnerMapper}), and an owner's
 * {@link Tenure tenure} measured in elapsed fiscal years.
 */
public final class FiscalYear {

    /** First month of the fiscal year. */
    private static final Month FISCAL_YEAR_START = Month.JULY;

    private FiscalYear() {
    }

    /** The calendar year in which the fiscal year containing {@code date} begins. */
    static int startYear(LocalDate date) {
        int year = date.getYear();
        return date.getMonthValue() >= FISCAL_YEAR_START.getValue() ? year : year - 1;
    }

    /** The last two digits of the starting calendar year of the fiscal year containing
     *  {@code date} — the {@code YY} shared by the fiscal-year label and the membership number. */
    static int shortYear(LocalDate date) {
        return startYear(date) % 100;
    }

    /** The fiscal-year label {@code "FY<YY>"} for {@code date}, or {@code null} when the date
     *  is absent. */
    static String label(LocalDate date) {
        return date == null ? null : String.format("FY%02d", shortYear(date));
    }

    /** Whole fiscal years elapsed from {@code from} to {@code to} — the number of 1 July
     *  boundaries crossed — never negative. Both dates must be non-null. */
    static long between(LocalDate from, LocalDate to) {
        return Math.max((long) startYear(to) - startYear(from), 0);
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.function.owner.AgeBand;
import org.springframework.samples.petclinic.rest.function.owner.CustomerCode;
import org.springframework.samples.petclinic.rest.function.owner.IdentityKey;
import org.springframework.samples.petclinic.rest.function.owner.Locality;
import org.springframework.samples.petclinic.rest.function.owner.Luhn;
import org.springframework.samples.petclinic.rest.function.owner.Salutation;
import org.springframework.samples.petclinic.rest.function.owner.TelephoneDisplay;
import org.springframework.samples.petclinic.rest.function.owner.Timezone;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.time.LocalDate;
import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "salutation", expression = "java(salutation(owner))")
    @Mapping(target = "displayName", expression = "java(displayName(owner))")
    @Mapping(target = "initials", expression = "java(initials(owner))")
    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
    @Mapping(target = "locality", expression = "java(locality(owner))")
    @Mapping(target = "timezone", expression = "java(timezone(owner))")
    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
    OwnerDto toOwnerDto(Owner owner);

    /** The owner's stored E.164 telephone formatted for humans; see {@link TelephoneDisplay}. */
    default String telephoneDisplay(Owner owner) {
        return TelephoneDisplay.of(owner.getTelephone());
    }

    /** The owner's derived identity key: normalized telephone, email and household id joined. */
    default String identityKey(Owner owner) {
        return IdentityKey.of(owner);
    }

    /** Whether the owner was flagged as a possible duplicate at registration, i.e. it carries
     *  the id of an existing owner it possibly duplicates. */
    default boolean possibleDuplicate(Owner owner) {
        return owner.getPossibleDuplicateOf() != null;
    }

    /** The owner's salutation: the optional title prefixed to the last name, or the last name
     *  alone when no title is on file; see {@link Salutation}. */
    default String salutation(Owner owner) {
        return Salutation.of(owner.getTitle(), owner.getLastName());
    }

    /** Format an owner's name for display as 'LastName, FirstName'. */
    default String displayName(Owner owner) {
        return owner.getLastName() + ", " + owner.getFirstName();
    }

    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
    default String initials(Owner owner) {
        return initial(owner.getFirstName()) + initial(owner.getLastName());
    }

    private String initial(String name) {
        return name == null || name.isEmpty() ? "" : Character.toUpperCase(name.charAt(0)) + ".";
    }

    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
     *  fiscal year of the registration date (see {@link FiscalYear}, e.g. 'SPR-SMI-0007-M26').
     *  Absent until both the customer code and registration date have been assigned. */
    default String membershipNumber(Owner owner) {
        String customerCode = owner.getCustomerCode();
        LocalDate registrationDate = owner.getRegistrationDate();
        if (customerCode == null || registrationDate == null) {
            return null;
        }
        return String.format("%s-M%02d", customerCode, FiscalYear.shortYear(registrationDate));
    }

    /** The owner's fiscal year, formatted 'FY&lt;YY&gt;' from the fiscal year of the
     *  registration date (see {@link FiscalYear}); absent until the registration date is set. */
    default String fiscalYear(Owner owner) {
        return FiscalYear.label(owner.getRegistrationDate());
    }

    /** The Luhn check digit (0-9) over the digits of the owner's customerCode; absent until the
     *  customer code has been assigned. */
    default Integer checkDigit(Owner owner) {
        String customerCode = owner.getCustomerCode();
        return customerCode == null ? null : Luhn.checkDigit(customerCode);
    }

    /** The owner's region, read back from the region segment of its customerCode (the identity's
     *  {@code <REGION>-<HASH8>} form). Until the customer code has been assigned it falls back to
     *  deriving the region from the postcode range first (NSW 2000-2099, VIC 3000-3099,
     *  QLD 4000-4099), then the city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
     *  Brisbane-&gt;QLD), or 'UNKNOWN' otherwise. */
    default String locality(Owner owner) {
        String region = CustomerCode.region(owner.getCustomerCode());
        return region != null ? region : Locality.region(owner.getCity(), owner.getPostcode());
    }

    /** The owner's IANA timezone, derived from its region ('locality') via the fixed
     *  region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
     *  QLD-&gt;Australia/Brisbane); absent when the region has no mapped timezone. */
    default String timezone(Owner owner) {
        return Timezone.of(locality(owner));
    }

    /** The owner's preferred contact channel: 'EMAIL' when an email address is on file,
     *  otherwise 'PHONE'. */
    default String contactPreference(Owner owner) {
        String email = owner.getEmail();
        return email != null && !email.isBlank() ? "EMAIL" : "PHONE";
    }

    /** The owner's age band at its registration date, derived from its birth date: 'MINOR'
     *  (under 18), 'ADULT' (18-64) or 'SENIOR' (65+); absent until a birth date is on file. */
    default String ageBand(Owner owner) {
        return AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate());
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

